<?php require_once __DIR__.'/../config/config.php';require_admin();$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{$date=$_POST['received_date']?:date('Y-m-d');$amount=(float)($_POST['amount']??0);$subject=trim($_POST['subject']??'');$pdo->prepare('INSERT INTO money_receipts(received_date,amount,subject) VALUES(?,?,?)')->execute([$date,$amount,$subject]);$rid=(int)$pdo->lastInsertId();$files=$_FILES['files']??[];if(isset($files['name'])&&is_array($files['name']))foreach($files['name'] as $i=>$name){if($name==='')continue;if(($files['error'][$i]??1)!==UPLOAD_ERR_OK)continue;$ext=strtolower(pathinfo($name,PATHINFO_EXTENSION));if(!in_array($ext,['pdf','doc','docx','jpg','jpeg','png','webp','xls','xlsx'],true))throw new Exception('فرمت یکی از فایل‌ها مجاز نیست.');$fn='receipt_'.uniqid('',true).'.'.$ext;move_uploaded_file($files['tmp_name'][$i],__DIR__.'/../uploads/'.$fn);$pdo->prepare('INSERT INTO receipt_files(receipt_id,file_path,original_name) VALUES(?,?,?)')->execute([$rid,$fn,$name]);}$msg='رسید تاییدی پول ثبت شد.';}catch(Exception $e){$err=$e->getMessage();}}
if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$pdo->prepare('DELETE FROM receipt_files WHERE receipt_id=?')->execute([$id]);$pdo->prepare('DELETE FROM money_receipts WHERE id=?')->execute([$id]);header('Location:receipts.php');exit;}$rows=$pdo->query('SELECT * FROM money_receipts ORDER BY id DESC')->fetchAll();require '../partials/header.php';?><section class="panel"><div class="section-title"><div><h2>رسید تاییدی پول</h2></div><a class="btn secondary" href="index.php">بخش مالی</a></div><?php if($msg):?><div class="badge">✓ <?=h($msg)?></div><?php endif;?><?php if($err):?><div class="alert">⚠ <?=h($err)?></div><?php endif;?><form method="post" enctype="multipart/form-data"><div class="row"><label>تاریخ دریافت پول<input required type="date" name="received_date" value="<?=date('Y-m-d')?>"></label><label>مقدار پول (افغانی)<input required type="number" step="0.01" name="amount"></label><label>بابت کدام موضوع<input required name="subject"></label><label>آپلود فایل (نامحدود)<input type="file" name="files[]" multiple></label></div><button>ثبت رسید تاییدی پول</button></form></section><section class="panel"><h3>رسیدهای ثبت‌شده</h3><div class="table-scroll"><table><tr><th>تاریخ دریافت</th><th>مقدار</th><th>موضوع</th><th>فایل‌ها</th><th>حذف</th></tr><?php foreach($rows as $x):?><tr><td><?=h($x['received_date'])?></td><td><?=money($x['amount'])?></td><td><?=h($x['subject'])?></td><td><?php $fs=$pdo->prepare('SELECT * FROM receipt_files WHERE receipt_id=? ORDER BY id');$fs->execute([$x['id']]);foreach($fs as $f):?><a href="../uploads/<?=h(rawurlencode($f['file_path']))?>" target="_blank"><?=h($f['original_name']?:'فایل')?></a><br><?php endforeach;?></td><td><a class="btn danger" href="?delete=<?=$x['id']?>" onclick="return confirm('این رسید حذف شود؟')">🗑 حذف</a></td></tr><?php endforeach;?></table></div></section><?php require '../partials/footer.php';?>